INSERT INTO official_prompts (id, slug, current_version, title, short_description, user_promise, collection, category, template_family, default_operation, input_mode, output_kind, complexity, required_input_summary, preservation_summary, badges, aliases, search_text, thumbnail_path, thumbnail_alt, featured_rank, active, created_at, updated_at) SELECT id, slug, current_version, title, short_description, user_promise, collection, category, template_family, default_operation, input_mode, output_kind, complexity, required_input_summary, preservation_summary, badges, aliases, search_text, thumbnail_path, thumbnail_alt, featured_rank, active, created_at, updated_at FROM official_prompts_staging WHERE 1 ON CONFLICT(id) DO UPDATE SET slug=excluded.slug, current_version=excluded.current_version, title=excluded.title, short_description=excluded.short_description, user_promise=excluded.user_promise, collection=excluded.collection, category=excluded.category, template_family=excluded.template_family, default_operation=excluded.default_operation, input_mode=excluded.input_mode, output_kind=excluded.output_kind, complexity=excluded.complexity, required_input_summary=excluded.required_input_summary, preservation_summary=excluded.preservation_summary, badges=excluded.badges, aliases=excluded.aliases, search_text=excluded.search_text, thumbnail_path=excluded.thumbnail_path, thumbnail_alt=excluded.thumbnail_alt, featured_rank=excluded.featured_rank, active=1, updated_at=excluded.updated_at;
INSERT INTO official_prompt_facets (prompt_id, facet_type, facet_value) SELECT prompt_id, facet_type, facet_value FROM official_prompt_facets_staging;
INSERT INTO official_prompt_fts (prompt_id, title, description, user_promise, aliases, search_text) SELECT id, title, short_description, user_promise, aliases, search_text FROM official_prompts WHERE active=1;
INSERT INTO official_prompt_catalog_meta (singleton, catalog_version, build_hash, published_at) VALUES (1, 'catalog-c793fa82ebe18c59', 'sha256:c793fa82ebe18c59fef155107c96a318912cba9854495665a70437e0b8e03e50', '2026-09-03T00:00:00Z') ON CONFLICT(singleton) DO UPDATE SET catalog_version=excluded.catalog_version, build_hash=excluded.build_hash, published_at=excluded.published_at;
